**Gates before launch.** I stop at the first gate that fails.

1. I check that spe/predictions/r04.yaml and spe/plans/r04.md are committed and show no changes in git status.
2. I run the grader selftest. grade.py must score the oracle file built from spe/evals/tasks/answers.json at 50 of 50 on both fields. It must fail an empty file and a file with shifted labels. I also give judge.md one known-good reply and one known-rude reply. It must pass the first and fail the second.
3. I regrade round 3's saved trial outputs with this round's grade.py as a control. If round 3's label accuracy changes, the grader changed. I log that in spe/failures.md before I go further.
4. I dry run this script with `args.only = ['B:T01', 'C2:T01', 'C2:T02']` and `trialsPerCell: 2`. Every trial must return valid output. The audit must find every transcript and report no peeks. grade.py must grade every line, and the judge must score every reply.
5. I replace the cost estimates in `args.costUsd` with the dry run's measured cost per call. If 500 trials plus grading, judging, and synthesis then project over $40, I halt and ask you. Otherwise the script would skip trials and leave cells short.

When every gate passes, I commit the script as `SPE r04 evaluate (harness)` and launch it.

**Defaults I chose:** a cell is one config on one ticket, so the run plans 500 trials. I pass the ticket text, config prompts, and tool lists in args with the answer fields removed. Trials call tools through round 3's fixture command, which sits outside spe/. grade.py takes `--answers` and `--input` and prints one JSON result per line.

Save as `spe/evals/harness/r04-workflow.js`:

```js
export const meta = {
  name: 'spe-round-eval',
  description: 'SPE eval: run every ticket under each config, void trials that peeked, grade labels with grade.py, judge reply tone blind with Opus, top up split cells, then run failure analysis and a completeness critic.',
  phases: [
    { title: 'Trials' },
    { title: 'Audit' },
    { title: 'Grade' },
    { title: 'Judge' },
    { title: 'Top-up' },
    { title: 'Synthesis' },
  ],
};

// Round lives here only. Prompts use ROUND or RR and never a hand-typed number.
const ROUND = args.round ?? 4;
const RR = String(ROUND).padStart(2, '0');

// Arguments
const CONFIG_NAMES = args.configNames ?? ['B', 'C2'];
const CONFIGS = args.configs;            // { B: { prompt, tools: [6 names] }, C2: { prompt, tools: [3 names + 'check_status'] } }
const TICKETS = args.tickets;            // [{ id, subject, body, customer }] with answer fields removed
const TICKET_FIELDS = args.ticketFields ?? ['id', 'subject', 'body', 'customer'];
const TRIALS = args.trialsPerCell ?? 5;
const ONLY = args.only ?? null;          // dry run cell keys such as 'B:T01'
const TOOL_CMD = args.toolCmd;           // round 3 fixture command, must live outside spe/
const TRANSCRIPT_DIR = args.transcriptDir;
const TRIAL_MODEL = args.trialModel ?? 'opus';
const JUDGE_MODEL = 'opus';
const WORKER_MODEL = 'opus';             // audit, grade runner, synthesis
const CAP = args.spendCapUsd ?? 40;
const COST = { trial: 0.04, audit: 0.05, grade: 0.10, judge: 0.08, synth: 1.50, ...(args.costUsd ?? {}) };
const TOPUP_PER_CELL = args.topUpPerCell ?? 3;
const TOPUP_MAX = args.topUpMaxTrials ?? 60;
const MAX_PEEK_RATE = args.maxPeekRate ?? 0.05;
const CONCURRENCY = args.concurrency ?? 20;
const AUDIT_BATCH = 50;
const GRADE_BATCH = 50;
const JUDGE_BATCH = args.judgeBatch ?? 10;
const SEED = args.seed ?? 1;
const PEEK_PATTERN = /spe\/|answers\.json|grade\.py|judge\.md/;

function fail(msg) {
  log(`HALT: ${msg}`);
  throw new Error(`HALT: ${msg}`);
}

// Input checks. A ticket that carries its answer is a leaked key.
if (!CONFIGS || !TICKETS || !TOOL_CMD || !TRANSCRIPT_DIR) {
  fail('args.configs, args.tickets, args.toolCmd, and args.transcriptDir are required');
}
for (const c of CONFIG_NAMES) {
  if (!CONFIGS[c] || typeof CONFIGS[c].prompt !== 'string' || !Array.isArray(CONFIGS[c].tools)) {
    fail(`config ${c} needs a prompt string and a tools array`);
  }
  if (PEEK_PATTERN.test(CONFIGS[c].prompt)) fail(`config ${c} prompt names an answer path, which would break the peek audit`);
}
if (!ONLY && TICKETS.length !== 50) fail(`expected 50 tickets, got ${TICKETS.length}`);
for (const t of TICKETS) {
  for (const k of ['category', 'priority', 'label', 'answer']) {
    if (k in t) fail(`ticket ${t.id} carries answer field "${k}"`);
  }
}
if (PEEK_PATTERN.test(TOOL_CMD)) fail('toolCmd points inside spe/, so every trial would look like a peek');

// Budget. Spend is estimated from per-call costs in args, not measured.
let spent = 0;
let pendingDownstream = 0;
let synthLeft = 2;
const skipped = [];
const DOWNSTREAM_PER_TRIAL = COST.audit / AUDIT_BATCH + COST.grade / GRADE_BATCH + COST.judge / JUDGE_BATCH;
const synthReserve = () => synthLeft * COST.synth;

function skip(kind, what, need) {
  skipped.push({ kind, what, est_usd: COST[kind] });
  log(`SKIP ${kind} ${what}: estimated spend would reach $${need.toFixed(2)}, cap is $${CAP}`);
  return false;
}
function reserveTrial(what) {
  const need = spent + COST.trial + (pendingDownstream + 1) * DOWNSTREAM_PER_TRIAL + synthReserve();
  if (need > CAP) return skip('trial', what, need);
  spent += COST.trial;
  pendingDownstream += 1;
  return true;
}
function reserve(kind, what) {
  const need = kind === 'synth' ? spent + synthReserve() : spent + COST[kind] + synthReserve();
  if (need > CAP) return skip(kind, what, need);
  spent += COST[kind];
  if (kind === 'synth') synthLeft -= 1;
  return true;
}

// Helpers
async function inChunks(thunks, size) {
  const out = [];
  for (let i = 0; i < thunks.length; i += size) {
    out.push(...(await parallel(thunks.slice(i, i + size))));
  }
  return out;
}
function batches(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}
function shuffled(arr, seed) {
  const a = arr.slice();
  let s = seed >>> 0;
  for (let i = a.length - 1; i > 0; i--) {
    s = (s * 1664525 + 1013904223) >>> 0;
    const j = s % (i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
const pick = (obj, keys) => Object.fromEntries(keys.filter((k) => k in obj).map((k) => [k, obj[k]]));
const round3 = (x) => +x.toFixed(3);
function mean(xs) {
  const v = xs.filter((x) => typeof x === 'number');
  return v.length ? round3(v.reduce((a, b) => a + b, 0) / v.length) : null;
}
function rate(xs, f) {
  return xs.length ? round3(xs.filter(f).length / xs.length) : null;
}

// Cells, ticket-major so the configs interleave
const cells = [];
for (const ticket of TICKETS) {
  for (const cfg of CONFIG_NAMES) {
    const key = `${cfg}:${ticket.id}`;
    if (!ONLY || ONLY.includes(key)) cells.push({ key, cfg, ticket });
  }
}
if (ONLY) {
  const missing = ONLY.filter((k) => !cells.some((c) => c.key === k));
  if (missing.length) fail(`args.only names cells that do not exist: ${missing.join(', ')}`);
}
log(`Round ${ROUND}: ${cells.length} cells x ${TRIALS} trials, cap $${CAP}, trial model ${TRIAL_MODEL}`);

// Schemas
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['ticket_id', 'label', 'reply', 'tool_calls', 'tool_errors', 'tools_used', 'files_read'],
  properties: {
    ticket_id: { type: 'string' },
    label: {
      type: 'object',
      required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    tool_calls: { type: 'integer', minimum: 0 },
    tool_errors: { type: 'integer', minimum: 0 },
    tools_used: { type: 'array', items: { type: 'string' } },
    files_read: { type: 'array', items: { type: 'string' } },
  },
};
const AUDIT_SCHEMA = {
  type: 'object',
  required: ['trials'],
  properties: {
    trials: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'found', 'peeked', 'paths', 'tokens', 'tool_calls', 'tool_errors'],
        properties: {
          trial_id: { type: 'string' },
          found: { type: 'boolean' },
          peeked: { type: 'boolean' },
          paths: { type: 'array', items: { type: 'string' } },
          tokens: { type: ['integer', 'null'] },
          tool_calls: { type: ['integer', 'null'] },
          tool_errors: { type: ['integer', 'null'] },
        },
      },
    },
  },
};
const GRADE_SCHEMA = {
  type: 'object',
  required: ['exit_code', 'results'],
  properties: {
    exit_code: { type: 'integer' },
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'category_ok', 'priority_ok'],
        properties: {
          trial_id: { type: 'string' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
        },
      },
    },
  },
};
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['items'],
  properties: {
    items: {
      type: 'array',
      items: {
        type: 'object',
        required: ['item_id', 'tone_score', 'tone_pass', 'reason'],
        properties: {
          item_id: { type: 'string' },
          tone_score: { type: 'integer', minimum: 1, maximum: 5 },
          tone_pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
};
const FAILURE_SCHEMA = {
  type: 'object',
  required: ['types', 'grader_suspects', 'notes'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'name', 'kind', 'what', 'how_to_spot', 'count_by_config', 'example_trials', 'fix'],
        properties: {
          id: { type: 'string', description: 'Existing F-number from spe/failures.md, or NEW' },
          name: { type: 'string' },
          kind: { type: 'string', enum: ['label-category', 'label-priority', 'tone', 'tool-use', 'grader', 'other'] },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          count_by_config: { type: 'object' },
          example_trials: { type: 'array', items: { type: 'string' } },
          fix: { type: 'string' },
        },
      },
    },
    grader_suspects: { type: 'array', items: { type: 'string' } },
    notes: { type: 'string' },
  },
};
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'ok_to_close_out', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    ok_to_close_out: { type: 'boolean' },
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        required: ['what', 'where', 'severity'],
        properties: {
          what: { type: 'string' },
          where: { type: 'string' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
        },
      },
    },
  },
};

// Prompts. Trial prompts never mention spe/, so any spe/ path in a trial transcript is a peek.
function trialPrompt(cell, id) {
  const cfg = CONFIGS[cell.cfg];
  return [
    `TRIAL_ID=${id}`,
    'You are a support agent. Follow the operating prompt below exactly.',
    '--- operating prompt ---',
    cfg.prompt,
    '--- end operating prompt ---',
    `Your tools are: ${cfg.tools.join(', ')}.`,
    `Call a tool only by running this shell command: ${TOOL_CMD} --config ${cell.cfg} --tool <name> --input '<json>'`,
    'The command prints JSON. A non-zero exit or an "error" field in the output is a tool error.',
    'Do not read, search, or list any files in the repository. Do not run any other command.',
    `Ticket ${cell.ticket.id}:`,
    JSON.stringify(pick(cell.ticket, TICKET_FIELDS), null, 2),
    'Label the ticket with a category and a priority, and write the reply you would send the customer.',
    'Return ticket_id, label, reply, your count of tool calls and tool errors, the tool names you used, and every file path you read (an empty list if none).',
  ].join('\n');
}
function auditPrompt(ids) {
  return [
    'You audit eval trial transcripts. Do not grade anything. Do not open any file under spe/.',
    `Transcripts are under ${TRANSCRIPT_DIR}. A trial transcript has its first user message start with the line TRIAL_ID=<id>.`,
    'If several files mention an id, use only the one whose first user message starts with that line. Ignore audit and grader transcripts.',
    'For each trial id below:',
    '1. Find its transcript. If there is none, set found=false and the other fields to false, [], or null.',
    '2. Check every tool call in it: file reads, searches, globs, and shell commands. Set peeked=true if any tool call input names a path containing "spe/" or the files answers.json, grade.py, or judge.md. List those paths.',
    `3. Count shell calls to the tool command (${TOOL_CMD}) as tool_calls. Count calls with a non-zero exit or an "error" field in the output as tool_errors.`,
    '4. Sum input and output tokens over the usage records into tokens. Use null if there are none.',
    'Trial ids:',
    ...ids,
  ].join('\n');
}
function gradePrompt(lines, file) {
  return [
    'Run the code grader. Do not grade by hand. Do not edit any file under spe/.',
    `1. Write the ${lines.length} lines between the markers to ${file}, byte for byte, one per line.`,
    `2. Run: python spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --input ${file}`,
    '3. Return the exit code and, for each output line, trial_id, category_ok, and priority_ok exactly as the grader printed them.',
    'If the grader errors, return its exit code and an empty results list.',
    '--- lines ---',
    ...lines,
    '--- end lines ---',
  ].join('\n');
}
function judgePrompt(batch) {
  const items = batch.map(({ item_id, t }) => {
    const tk = TICKETS.find((x) => x.id === t.ticket_id);
    return { item_id, ticket: { subject: tk.subject, body: tk.body }, reply: t.out.reply };
  });
  return [
    'You are the tone judge. Read spe/evals/graders/judge.md and apply its rubric exactly.',
    'Score only the tone of each reply. Ignore whether the category or priority is right.',
    'You are not told which configuration wrote a reply. Do not guess.',
    'Return one entry per item_id with tone_score (1 to 5), tone_pass as the rubric defines it, and a one-sentence reason.',
    JSON.stringify(items, null, 2),
  ].join('\n');
}

// Stages
async function runTrial(cell, n, topUp, phaseName) {
  const id = `${cell.cfg}-${cell.ticket.id}-${topUp ? 'u' : 't'}${n}`;
  const base = { id, cfg: cell.cfg, ticket_id: cell.ticket.id, key: cell.key, topUp };
  for (let attempt = 1; attempt <= 2; attempt++) {
    if (!reserveTrial(attempt === 1 ? id : `${id} retry`)) return { ...base, status: 'skipped' };
    const t0 = Date.now();
    try {
      const out = await agent(trialPrompt(cell, id), { label: id, phase: phaseName, schema: TRIAL_SCHEMA, model: TRIAL_MODEL });
      return { ...base, status: 'completed', out, runtime_ms: Date.now() - t0, attempts: attempt };
    } catch (e) {
      log(`harness error ${id} attempt ${attempt}: ${String(e).slice(0, 200)}`);
      if (attempt === 2) return { ...base, status: 'harness_error', error: String(e).slice(0, 500) };
    }
  }
}

async function audit(trials, phaseName) {
  const done = trials.filter((t) => t.status === 'completed');
  const thunks = batches(done, AUDIT_BATCH).map((b, i) => async () => {
    const label = `audit-${phaseName}-${i}`;
    const markUnaudited = () => b.forEach((t) => { t.status = 'unaudited'; });
    if (!reserve('audit', label)) return markUnaudited();
    let res;
    try {
      res = await agent(auditPrompt(b.map((t) => t.id)), { label, phase: phaseName, schema: AUDIT_SCHEMA, model: WORKER_MODEL });
    } catch (e) {
      log(`audit harness error ${label}: ${String(e).slice(0, 200)}`);
      return markUnaudited();
    }
    const byId = new Map(res.trials.map((r) => [r.trial_id, r]));
    for (const t of b) {
      const r = byId.get(t.id);
      const selfPeek = t.out.files_read.filter((p) => PEEK_PATTERN.test(p));
      if (!r || !r.found) { t.status = 'unaudited'; continue; }
      t.tokens = r.tokens;
      t.audit_tool_calls = r.tool_calls;
      t.audit_tool_errors = r.tool_errors;
      if (r.peeked || selfPeek.length) {
        t.status = 'voided_peek';
        t.peek_paths = [...r.paths, ...selfPeek];
        log(`VOID ${t.id}: ${t.peek_paths.join(', ')}`);
      } else if (t.out.files_read.length) {
        t.read_files_flag = t.out.files_read;
      }
    }
  });
  await inChunks(thunks, CONCURRENCY);
  const voided = done.filter((t) => t.status === 'voided_peek').length;
  const unaudited = done.filter((t) => t.status === 'unaudited').length;
  log(`${phaseName} audit: ${done.length} completed, ${voided} voided for peeking, ${unaudited} unaudited`);
  if (done.length && voided / done.length > MAX_PEEK_RATE) {
    fail(`${voided} of ${done.length} trials read answer paths. The answer key is reachable from trials. Fix isolation before rerunning.`);
  }
}

async function grade(trials, phaseName) {
  const ready = trials.filter((t) => t.status === 'completed');
  const thunks = batches(ready, GRADE_BATCH).map((b, i) => async () => {
    const label = `grade-${phaseName}-${i}`;
    const markUngraded = () => b.forEach((t) => { t.status = 'ungraded'; });
    if (!reserve('grade', label)) return markUngraded();
    const lines = b.map((t) => JSON.stringify({
      trial_id: t.id,
      ticket_id: t.ticket_id,
      label: { category: t.out.label.category, priority: t.out.label.priority },
    }));
    const file = `/tmp/spe-r${RR}-${label}.jsonl`;
    let res;
    try {
      res = await agent(gradePrompt(lines, file), { label, phase: phaseName, schema: GRADE_SCHEMA, model: WORKER_MODEL });
    } catch (e) {
      log(`grade harness error ${label}: ${String(e).slice(0, 200)}`);
      return markUngraded();
    }
    if (res.exit_code !== 0) fail(`grade.py exited ${res.exit_code} on ${label}. The grader is broken.`);
    const byId = new Map(res.results.map((r) => [r.trial_id, r]));
    if (byId.size !== b.length || b.some((t) => !byId.has(t.id))) {
      fail(`grade.py returned ${byId.size} results for ${b.length} lines on ${label}. The grader is broken.`);
    }
    for (const t of b) {
      const r = byId.get(t.id);
      t.category_ok = r.category_ok;
      t.priority_ok = r.priority_ok;
      t.label_ok = r.category_ok && r.priority_ok;
      t.status = 'graded';
    }
  });
  await inChunks(thunks, CONCURRENCY);
}

async function judge(trials, phaseName, seed) {
  const ready = shuffled(trials.filter((t) => t.status === 'graded'), seed);
  const tag = phaseName === 'Top-up' ? 'U' : 'M';
  const items = ready.map((t, i) => ({ item_id: `${tag}${i + 1}`, t }));
  const thunks = batches(items, JUDGE_BATCH).map((b, i) => async () => {
    const label = `judge-${phaseName}-${i}`;
    if (!reserve('judge', label)) return;
    let res;
    try {
      res = await agent(judgePrompt(b), { label, phase: phaseName, schema: JUDGE_SCHEMA, model: JUDGE_MODEL });
    } catch (e) {
      log(`judge harness error ${label}: ${String(e).slice(0, 200)}`);
      return;
    }
    const byId = new Map(res.items.map((r) => [r.item_id, r]));
    for (const { item_id, t } of b) {
      const r = byId.get(item_id);
      if (r) t.tone = { score: r.tone_score, pass: r.tone_pass, reason: r.reason };
    }
  });
  await inChunks(thunks, CONCURRENCY);
  const unjudged = ready.filter((t) => !t.tone).length;
  if (unjudged) log(`${phaseName}: ${unjudged} graded trials have no tone score`);
  pendingDownstream = 0;
}

// Trials. Trial k runs for every cell before trial k+1, so a budget stop shortens every cell evenly.
phase('Trials');
const mainThunks = [];
for (let k = 1; k <= TRIALS; k++) {
  for (const cell of cells) mainThunks.push(() => runTrial(cell, k, false, 'Trials'));
}
const main = await inChunks(mainThunks, CONCURRENCY);

phase('Audit');
await audit(main, 'Audit');

phase('Grade');
await grade(main, 'Grade');

phase('Judge');
await judge(main, 'Judge', SEED);

// Top-up: cells where some trials passed and some failed, most even splits first
phase('Top-up');
const splitCells = cells
  .map((cell) => {
    const g = main.filter((t) => t.key === cell.key && t.status === 'graded');
    const labelPass = g.filter((t) => t.label_ok).length;
    const toned = g.filter((t) => t.tone);
    const tonePass = toned.filter((t) => t.tone.pass).length;
    const labelSplit = labelPass > 0 && labelPass < g.length;
    const toneSplit = tonePass > 0 && tonePass < toned.length;
    return { cell, split: labelSplit || toneSplit, evenness: g.length ? Math.abs(labelPass / g.length - 0.5) : 1 };
  })
  .filter((x) => x.split)
  .sort((a, b) => a.evenness - b.evenness)
  .map((x) => x.cell);
const topUpCells = splitCells.slice(0, Math.floor(TOPUP_MAX / TOPUP_PER_CELL));
if (splitCells.length > topUpCells.length) {
  log(`Top-up cap of ${TOPUP_MAX} trials: ${splitCells.length - topUpCells.length} split cells get no extra trials`);
}
log(`Top-up: ${topUpCells.length} split cells x ${TOPUP_PER_CELL} trials`);
const topUpThunks = [];
for (let k = 1; k <= TOPUP_PER_CELL; k++) {
  for (const cell of topUpCells) topUpThunks.push(() => runTrial(cell, k, true, 'Top-up'));
}
const topUp = await inChunks(topUpThunks, CONCURRENCY);
await audit(topUp, 'Top-up');
await grade(topUp, 'Top-up');
await judge(topUp, 'Top-up', SEED + 1);

// Metrics. Only graded trials count. Harness errors, skips, voids, and unaudited trials are reported apart.
const all = [...main, ...topUp];
function summarize(trials) {
  const out = {};
  for (const cfg of CONFIG_NAMES) {
    const mine = trials.filter((t) => t.cfg === cfg);
    const graded = mine.filter((t) => t.status === 'graded');
    const toned = graded.filter((t) => t.tone);
    const calls = graded.reduce((a, t) => a + (t.audit_tool_calls ?? 0), 0);
    const errs = graded.reduce((a, t) => a + (t.audit_tool_errors ?? 0), 0);
    const count = (s) => mine.filter((t) => t.status === s).length;
    out[cfg] = {
      n_attempted: mine.length,
      n_graded: graded.length,
      n_skipped: count('skipped'),
      n_harness_error: count('harness_error'),
      n_voided_peek: count('voided_peek'),
      n_unaudited: count('unaudited'),
      n_ungraded: count('ungraded'),
      n_tone_scored: toned.length,
      category_acc: rate(graded, (t) => t.category_ok),
      priority_acc: rate(graded, (t) => t.priority_ok),
      label_acc: rate(graded, (t) => t.label_ok),
      tone_pass_rate: rate(toned, (t) => t.tone.pass),
      tone_mean: mean(toned.map((t) => t.tone.score)),
      runtime_s_mean: mean(graded.map((t) => t.runtime_ms / 1000)),
      tool_calls_mean: mean(graded.map((t) => t.audit_tool_calls)),
      tool_calls_self_reported_mean: mean(graded.map((t) => t.out.tool_calls)),
      tool_errors_mean: mean(graded.map((t) => t.audit_tool_errors)),
      tool_error_rate: calls ? round3(errs / calls) : null,
      tokens_mean: mean(graded.map((t) => t.tokens)),
      ticket_id_mismatches: graded.filter((t) => t.out.ticket_id !== t.ticket_id).length,
    };
  }
  return out;
}
const primary = summarize(main);          // planned trials only, scored against the prediction
const withTopUp = summarize(all);         // split cells weigh more here, so this is context only
const perCell = cells.map((cell) => {
  const g = all.filter((t) => t.key === cell.key && t.status === 'graded');
  const gMain = g.filter((t) => !t.topUp);
  return {
    cell: cell.key,
    graded_planned: gMain.length,
    label_pass_planned: gMain.filter((t) => t.label_ok).length,
    tone_pass_planned: gMain.filter((t) => t.tone && t.tone.pass).length,
    graded_top_up: g.length - gMain.length,
    label_pass_all: g.filter((t) => t.label_ok).length,
  };
});

// Synthesis: failure analysis, then the completeness critic
phase('Synthesis');
const failed = all
  .filter((t) => t.status === 'graded' && (!t.label_ok || (t.tone && !t.tone.pass)))
  .map((t) => ({
    trial_id: t.id,
    cfg: t.cfg,
    ticket_id: t.ticket_id,
    top_up: t.topUp,
    label: t.out.label,
    category_ok: t.category_ok,
    priority_ok: t.priority_ok,
    tone: t.tone ?? null,
    tool_calls: t.audit_tool_calls,
    tool_errors: t.audit_tool_errors,
    tools_used: t.out.tools_used,
    reply_excerpt: t.out.reply.slice(0, 300),
  }));

let failures = null;
if (reserve('synth', 'failure-analysis')) {
  try {
    failures = await agent([
      `You analyse failures from SPE round ${ROUND}.`,
      `Configs and their tools: ${CONFIG_NAMES.map((c) => `${c}: ${CONFIGS[c].tools.join(', ')}`).join(' | ')}.`,
      'Read spe/failures.md for the existing F-numbered failure types and spe/evals/tasks/answers.json for the expected labels.',
      'Do not read spe/predictions/ or spe/plans/. Close-out compares results with predictions later, so this analysis stays independent of them.',
      'Group the failed trials below into failure types. Reuse an existing F-number when one fits, and mark the type NEW when none does.',
      'For each type give the name, kind, what happened, how to spot it, counts per config, up to 5 example trial ids, and a proposed fix.',
      'List in grader_suspects any trial where the answer key or the grader looks wrong rather than the agent. A grader bug is a failure type of its own.',
      `Primary metrics (planned trials only): ${JSON.stringify(primary)}`,
      `Failed trials: ${JSON.stringify(failed)}`,
    ].join('\n'), { label: 'failure-analysis', phase: 'Synthesis', schema: FAILURE_SCHEMA, model: WORKER_MODEL });
  } catch (e) {
    log(`failure analysis harness error: ${String(e).slice(0, 200)}`);
  }
}

let critic = null;
if (reserve('synth', 'completeness-critic')) {
  const shortCells = perCell.filter((c) => c.graded_planned < TRIALS).map((c) => `${c.cell} (${c.graded_planned}/${TRIALS})`);
  try {
    critic = await agent([
      `You are the completeness critic for SPE round ${ROUND}. Decide whether this run supports close-out.`,
      `Read spe/predictions/r${RR}.yaml only to confirm that every predicted metric has a measured value for every config below. Do not compare the values.`,
      'Name every gap: cells short of planned trials, metrics computed on a small n, phases that missed valid trials, skipped work, unjudged replies, and anything the failure analysis left out.',
      `Planned: ${cells.length} cells x ${TRIALS} trials. Dry run: ${Boolean(ONLY)}.`,
      `Cells short of planned graded trials: ${shortCells.length ? shortCells.join(', ') : 'none'}`,
      `Skipped for budget: ${JSON.stringify(skipped)}`,
      `Estimated spend: $${spent.toFixed(2)} of $${CAP}.`,
      `Primary metrics: ${JSON.stringify(primary)}`,
      `Metrics with top-up: ${JSON.stringify(withTopUp)}`,
      `Failure analysis: ${failures ? JSON.stringify(failures) : 'did not run'}`,
      'Judge note: the tone judge is Opus, the same family as the trials. No judge from another family was available.',
    ].join('\n'), { label: 'completeness-critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: WORKER_MODEL });
  } catch (e) {
    log(`completeness critic harness error: ${String(e).slice(0, 200)}`);
  }
}

log(`Done. Estimated spend $${spent.toFixed(2)} of $${CAP}. ${skipped.length} calls skipped for budget.`);

return {
  round: ROUND,
  dry_run: Boolean(ONLY),
  trial_model: TRIAL_MODEL,
  judge_model: JUDGE_MODEL,
  judge_note: 'The tone judge is Opus, the same model family as the trials. No judge from another family was available, so shared blind spots are possible.',
  spend: { estimated_usd: +spent.toFixed(2), cap_usd: CAP, note: 'Estimated from per-call costs in args.costUsd. Not measured.' },
  skipped,
  primary,
  with_top_up: withTopUp,
  per_cell: perCell,
  failures,
  critic,
  trials: all.map((t) => ({
    id: t.id,
    cfg: t.cfg,
    ticket_id: t.ticket_id,
    top_up: t.topUp,
    status: t.status,
    attempts: t.attempts ?? null,
    runtime_ms: t.runtime_ms ?? null,
    tokens: t.tokens ?? null,
    tool_calls: t.audit_tool_calls ?? null,
    tool_errors: t.audit_tool_errors ?? null,
    label: t.out ? t.out.label : null,
    reply: t.out ? t.out.reply : null,
    category_ok: t.category_ok ?? null,
    priority_ok: t.priority_ok ?? null,
    label_ok: t.label_ok ?? null,
    tone: t.tone ?? null,
    peek_paths: t.peek_paths ?? null,
    read_files_flag: t.read_files_flag ?? null,
    error: t.error ?? null,
  })),
};
